import (
	"context"
	"database/sql"
	"errors"

	"encore.dev/storage/sqldb"
)

// Task represents a task in the task manager.
type Task struct {
	ID          int64  `json:"id"`
	Title       string `json:"title"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// CreateTaskParams defines the parameters for creating a task.
